#!/usr/bin/env python3
import json,os,sys
from pathlib import Path
import nbformat
from nbclient import NotebookClient
ROOT=Path(__file__).resolve().parents[4]
BASE=ROOT/'Experiment/01_behavioral_diversity'
md=nbformat.v4.new_markdown_cell;code=nbformat.v4.new_code_cell
cells=[md('# Final-response semantic separation and illustrative trajectories\n\nTwo main panels only: A, role-separated persona-pair heatmaps; B, two question-controlled case studies. The user selected trial 1 only for all five settings: off/155/001/003/046. Panel A compares across-persona and within-persona final-response distances across distinct questions within super-family, with question-wise label-swap tests. Only the lower triangle is displayed; the diagonal is light gray and the redundant upper triangle is hidden. Heatmap axis lines, question-count headings, subtitles and bottom explanatory text are omitted from the graphic. Persona labels and the colorbar remain; statistical definitions and caveats are documented in this notebook and the report. Panel B retains the selected case IDs and is refitted for the current persona panel. Existing figures remain separate.'),
 code("from pathlib import Path\nimport sys,json,csv\nfrom IPython.display import display,Markdown,Image,Code\nROOT=next(p for p in [Path.cwd(),*Path.cwd().parents] if (p/'Experiment/shared/task_selection.csv').exists())\nsys.path.insert(0,str(ROOT/'Experiment/01_behavioral_diversity/code/semantic'))\nimport analyze,plot,final_response,final_report\nc=analyze.config()\ndisplay(Markdown('```json\\n'+json.dumps({k:c[k] for k in ['arms','labels','model_id','model_revision','display_rollout']},indent=2)+'\\n```'))"),
 md('## Data and embedding provenance\nCurrent messages are encoded independently for simulator and actor, without system prompts, profiles, metadata or repeated history. Frozen Qwen3-Embedding-0.6B local weights; last-token pooling; normalized vectors. Extraction/embedding are separate resumable steps so notebook reruns do not launch inference.'),
 code("provenance=json.loads((analyze.OUT/'provenance.json').read_text())\nprint('Original base extraction message count:',provenance['message_count'])\nprint('Original base extraction complete episodes:',provenance['eligible_episodes'])\nprint('Additional persona 003 extraction:',json.loads((analyze.OUT/'persona_003_embedding_provenance.json').read_text())['messages'],'messages')\nprint(json.dumps(json.loads((analyze.CACHE/'embedding_provenance.json').read_text()),indent=2))"),
 md('## Aggregate before projection\nSelect the last nonempty generated message per role from each complete trial-1 interaction. Use a common question set across all five personas and both roles. Within each super-family, compare cross-persona distances across distinct questions with the two within-persona means across distinct questions. Average four family effects equally. No same-question distances enter the statistic. Swap persona labels within questions for 10,000 one-sided permutations; apply Holm correction across 20 tests. Bootstrap whole questions within benchmark × family 20,000 times for pointwise 95% CIs, retaining all personas and excluding same-original-question pairs even for duplicated sampled questions.'),
 code("RECOMPUTE=False  # Set True to rerun permutations and bootstrap from cached embeddings.\nif RECOMPUTE or not (final_response.DEST/'summary.json').exists(): final_response.main()\nsaved=json.loads((final_response.DEST/'summary.json').read_text())\nsummary=saved['roles']\nfinal_report.main()\ndisplay(Markdown('```json\\n'+json.dumps(saved['methods'],indent=2)+'\\n```'))\nprint(json.dumps({role:{k:v for k,v in values.items() if k in ['questions','source_counts','family_counts']} for role,values in summary.items()},indent=2))"),
 code("rows=list(csv.DictReader((final_response.DEST/'heatmap_cells.csv').open()))\nfor role in c['roles']:\n    text=['### '+role,'','| Pair | Excess [95% CI] | Holm p | Questions |','|---|---|---:|---:|']\n    for r in rows:\n        if r['role']==role:\n            text.append(f\"| {c['labels'][r['persona_i']]} / {c['labels'][r['persona_j']]} | {float(r['estimate']):.4f} [{float(r['ci_low']):.4f}, {float(r['ci_high']):.4f}] | {float(r['p_holm']):.5f} | {r['questions']} |\")\n    display(Markdown('\\n'.join(text)))"),
 md('## Case studies and plotting\nPersona 003 is an exploratory replacement after inspecting the 004 and 089 panels; its instructed output language is Russian, so semantic separation may reflect language. The user manually selected bix-57-q1 and matToolUse/disambiguation/case_236 after reviewing the long-interaction gallery. These are illustrative, not representative examples. Rollout 1 is displayed for every persona and both roles; UMAP is refitted after replacing persona 089 with 003, using the same two cases and parameters: cosine metric, up to 15 neighbors, min_dist=0.1, 500 epochs and seed 42. All five settings jointly define each question–role map. Actual lengths are retained. Hollow circles mark starts, larger solid circles mark ends, and small solid dots mark intermediate rounds. A single-node trajectory uses a solid dot inside a hollow circle. Directional arrows are omitted. Gentle quadratic curves connect consecutive observed nodes for visual clarity; intermediate positions do not represent observed states. The control-point offset is 0.14 times the perpendicular chord in axis-normalized coordinates; endpoints are fixed. Point indices are omitted from the figure; round indices remain in source data. Local projections are not comparable across plots.'),
 code("display(Markdown('```json\\n'+(analyze.OUT/'cases.json').read_text()+'\\n```'))\ndisplay(Code(Path(plot.__file__).read_text(),language='python'))\nplot.main()\ndisplay(Image(filename=str(plot.FIG/'semantic.png'),width=1200))"),
 code("import numpy as np\nfor role,v in summary.items():\n    m=np.asarray(v['estimate']);assert np.allclose(m,m.T)\n    assert np.all(np.diag(m)==0)\n    assert np.isfinite(m).all()\nassert len(rows)==10*len(c['roles'])\nassert all(float(r['p_holm'])>=float(r['p_permutation'])-1e-12 for r in rows)\nassert len({v['questions'] for v in summary.values()})==1\ncoords=list(csv.DictReader((analyze.OUT/'trajectory_coordinates.csv').open()))\nshown=[r for r in coords if r['displayed']=='True']\nassert {int(r['trial']) for r in shown}=={c['display_rollout']}\nassert {r['arm'] for r in shown}==set(c['arms'])\nprint('Validated: symmetric heatmaps, ten comparisons per role, fixed displayed rollout, all five settings, finite estimates.')"),
 md('## Interpretation\nPanel A is aggregate evidence scoped to the matched selected questions. Panel B is illustrative. Within-persona spread includes differences across questions, not repeated-rollout randomness. Inference is conditional on the observed trial and question-wise exchangeability. Stars use Holm-adjusted one-sided permutation p<0.05; CIs are pointwise and need not agree with adjusted decisions. This is an exploratory analysis. Language/style can affect distance; neither cosine distance nor a UMAP path measures task or reasoning quality. Full intervals, exact p values, source/family counts and endpoint definitions are in `SEMANTIC_REPORT.md`.')]

cells.insert(1,md('[Candidate manuscript caption and complete figure handoff](SEMANTIC_FIGURE_CAPTION.md)'))

def main():
 runtime=Path('/tmp/psb-analysis-jupyter');kernel=runtime/'kernels/python3';kernel.mkdir(parents=True,exist_ok=True)
 (kernel/'kernel.json').write_text(json.dumps({'argv':[str(ROOT/'.venv/bin/python'),'-m','ipykernel_launcher','-f','{connection_file}'],'display_name':'Python (PersonaScienceBench)','language':'python'}))
 os.environ.update(JUPYTER_PATH=str(runtime),JUPYTER_RUNTIME_DIR=str(runtime/'runtime'),IPYTHONDIR=str(runtime/'ipython'),MPLCONFIGDIR='/tmp/psb-mpl',OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='1')
 nb=nbformat.v4.new_notebook(cells=cells,metadata={'kernelspec':{'name':'python3','display_name':'Python (PersonaScienceBench)','language':'python'}})
 path=BASE/'semantic_trajectory_analysis.ipynb';nbformat.write(nb,path)
 NotebookClient(nb,timeout=600,startup_timeout=60,kernel_name='python3',resources={'metadata':{'path':str(ROOT)}}).execute()
 nbformat.validate(nb);nbformat.write(nb,path);print('Executed semantic notebook:',len([c for c in nb.cells if c.cell_type=='code']),'code cells',flush=True)

if __name__=='__main__':main()
